// https://docs.rs/diesel_migrations/latest/diesel_migrations/macro.embed_migrations.html
// Due to limitations in rusts proc-macro API there is currently no way to signal that a
// specific proc macro should be rerun if some external file changes/is added. This implies
// that embed_migrations! cannot regenerate the list of embedded migrations if only the
// migrations are changed. This limitation can be solved by adding a custom build.rs file
// to your crate, such that the crate is rebuild if the migration directory changes.
fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("cargo:rerun-if-changed=migrations");
    println!("cargo:rerun-if-changed=src/generated/schema.rs");

    if let Err(e) = parse_schema_rs() {
        eprintln!("parse_schema_rs error: {e}");
        return Err(e);
    }

    Ok(())
}

fn parse_schema_rs() -> Result<(), Box<dyn std::error::Error>> {
    use std::fmt::Write as _;
    use std::fs;
    use std::path::Path;

    let manifest_dir = std::env::var("CARGO_MANIFEST_DIR")?;
    let schema_path = Path::new(&manifest_dir).join("src/generated/schema.rs");
    let schema_content = fs::read_to_string(&schema_path)?;

    let mut entries: Vec<(String, String, String)> = Vec::new();
    let mut lines: Vec<&str> = schema_content.lines().collect();
    lines.push("");

    let mut i = 0usize;
    let mut table_name = String::new();
    while i < lines.len() {
        let line = lines.get(i).map_or("", |l| l.trim());

        if line.starts_with("diesel::table!") {
            table_name.clear();
            i = i.saturating_add(1);
            while i < lines.len() {
                let inner_line = lines.get(i).map_or("", |l| l.trim());
                if inner_line.contains("(id)") {
                    let part = inner_line.split('(').next().unwrap_or("");
                    table_name = part.trim().to_string();
                    break;
                }
                i = i.saturating_add(1);
            }
        }

        if !table_name.is_empty() && line.contains("->") {
            let parts: Vec<&str> = line.split("->").collect();
            if parts.len() == 2 {
                let col_name = parts.first().map_or("", |s| s.trim());
                let type_part = parts.get(1).map_or("", |s| s.trim().trim_end_matches(','));
                let sql_type = map_sql_type(type_part);
                let tn = table_name.clone();
                entries.push((tn, col_name.to_string(), sql_type.to_string()));
            }
        }

        if line == "}" && !table_name.is_empty() {
            table_name.clear();
        }

        i = i.saturating_add(1);
    }

    entries.sort_by(|a, b| {
        let t = a.0.cmp(&b.0);
        if t == std::cmp::Ordering::Equal {
            a.1.cmp(&b.1)
        } else {
            t
        }
    });

    let src_dir = Path::new(&manifest_dir).join("src");
    let dest_path = src_dir.join("generated/columns.rs");
    let header = concat!(
        "//! Auto-generated column constants from the Diesel schema. Do not edit.\n",
        "\n",
        "#![allow(missing_docs)]\n",
        "\n",
        "#[doc(hidden)]\n",
        "pub const SCHEMA_ENTRIES: &[(&str, &str, &str)] = &[\n",
    );
    let mut output = String::from(header);
    for entry in &entries {
        let escaped_table = entry.0.replace('"', "\\\"");
        let escaped_col = entry.1.replace('"', "\\\"");
        let escaped_type = entry.2.replace('"', "\\\"");
        let _ = writeln!(
            output,
            "    (\"{escaped_table}\", \"{escaped_col}\", \"{escaped_type}\"),"
        );
    }
    output.push_str("];\n");

    fs::write(dest_path, output)?;

    Ok(())
}

fn map_sql_type(diesel_type: &str) -> &'static str {
    let inner = diesel_type
        .strip_prefix("Nullable<")
        .and_then(|s| s.strip_suffix('>'))
        .unwrap_or(diesel_type);
    match inner {
        "Integer" | "Bool" => "INTEGER",
        "Timestamp" => "TIMESTAMP",
        "Binary" => "BLOB",
        "Double" => "DOUBLE",
        _ => "TEXT",
    }
}

//! Flutter Rust Bridge API surface.
//!
//! This module defines the functions and types exposed to Dart via FRB.

use crate::mobile_api::{
    MobileContactInfo, MobileContactRow, MobileDeviceInfo, MobileInitStatus, MobilePeerStatus,
};
use crate::mobile_node::{
    ChatMessage, MobileGroup, MobileGroupMessage, MobilePeerRecord, SwarmEventJson,
};
use crate::network::NetworkSize;

/// Initialize the mobile database at the given path and return peer info.
///
/// # Errors
/// Returns an error if the database cannot be opened or initialized.
pub fn init_mobile_database(db_path: String) -> Result<MobileInitStatus, String> {
    crate::mobile_api::init_mobile_database(db_path)
}

/// Get current peer status (DB URL, peer ID, nickname).
///
/// # Errors
/// Returns an error if the status cannot be retrieved.
pub fn get_mobile_peer_status() -> Result<MobilePeerStatus, String> {
    crate::mobile_api::get_mobile_peer_status()
}

/// Start the p2p node: init DB, build swarm, begin listening.
///
/// # Errors
/// Returns an error if the node fails to start.
pub fn start_node(db_path: String) -> Result<String, String> {
    crate::mobile_node::start_node(db_path)
}

/// Start the p2p node with automatic DB selection (lock-based, same as TUI).
/// Scans CWD for unlocked .db files, picks the first one, or creates a new one.
///
/// # Errors
/// Returns an error if the node fails to start.
pub fn start_node_auto() -> Result<String, String> {
    crate::mobile_node::start_node_auto()
}

/// Stop the p2p node.
///
/// # Errors
/// Returns an error if the node fails to stop.
pub fn stop_node() -> Result<(), String> {
    crate::mobile_node::stop_node()
}

/// Get all stored TUI log messages (for Log tab display).
#[must_use]
pub fn get_logs() -> Vec<String> {
    crate::logging::get_tui_logs()
}

/// Clear the in-memory TUI log buffer (Log tab "Clear" action).
pub fn clear_logs() {
    crate::logging::clear_tui_logs();
}

/// Poll the next swarm event (non-blocking).
///
/// # Errors
/// Returns an error if polling the swarm event fails.
pub fn poll_event() -> Result<Option<SwarmEventJson>, String> {
    crate::mobile_node::poll_event()
}

/// Get all known peers with nicknames.
///
/// This is retained as the home of the generated [`MobilePeerRecord`] Dart
/// type; Flutter's peer table prefers the single round trip
/// [`crate::mobile_api::get_peers_with_stats`].
///
/// # Errors
/// Returns an error if the peers cannot be loaded.
pub fn get_known_peers() -> Result<Vec<MobilePeerRecord>, String> {
    crate::mobile_node::get_known_peers()
}

// --- Message history ---

/// Load broadcast chat messages (chronological order).
///
/// # Errors
/// Returns an error if the messages cannot be loaded.
pub fn load_broadcast_messages(limit: i64) -> Result<Vec<ChatMessage>, String> {
    crate::mobile_node::load_broadcast_messages(limit)
}

/// Load DM history with a specific peer (chronological order).
///
/// # Errors
/// Returns an error if the messages cannot be loaded.
pub fn load_dm_messages(peer_id: String, limit: i64) -> Result<Vec<ChatMessage>, String> {
    crate::mobile_node::load_dm_messages(peer_id, limit)
}

/// Save an outgoing broadcast message to DB and send via swarm.
/// `attachment_path`, when present, is stored content-addressedly (files lane
/// §12) and sent as an attachment descriptor on the message.
///
/// # Errors
/// Returns an error if the message cannot be saved, sent, or the attachment
/// stored/read.
pub fn save_outgoing_broadcast(
    content: String,
    attachment_path: Option<String>,
) -> Result<ChatMessage, String> {
    crate::mobile_node::save_outgoing_broadcast(content, attachment_path)
}

/// Save an outgoing DM to DB and send via swarm. `attachment_path`, when
/// present, is stored content-addressedly (files lane §12) and sent as an
/// attachment descriptor on the message.
///
/// # Errors
/// Returns an error if the message cannot be saved, sent, or the attachment
/// stored/read.
pub fn save_outgoing_dm(
    peer_id: String,
    content: String,
    attachment_path: Option<String>,
) -> Result<ChatMessage, String> {
    crate::mobile_node::save_outgoing_dm(peer_id, content, attachment_path)
}

/// Save an incoming message (broadcast or DM) to the database.
///
/// `latency` is the live event's measured round-trip time; it only decorates
/// the returned message (never persisted), mirroring the TUI.
///
/// # Errors
/// Returns an error if the message cannot be saved.
pub fn save_incoming_message(
    content: String,
    peer_id: String,
    is_direct: bool,
    nickname: Option<String>,
    latency: Option<String>,
) -> Result<ChatMessage, String> {
    crate::mobile_node::save_incoming_message(content, peer_id, is_direct, nickname, latency)
}

// --- Groups ---

/// Create (or join) a public group by name and subscribe to its topic.
///
/// # Errors
/// Returns an error if the group cannot be created.
pub fn create_group(name: &str) -> Result<MobileGroup, String> {
    crate::mobile_node::create_group(name)
}

/// List all known groups with their member counts.
///
/// # Errors
/// Returns an error if the groups cannot be loaded.
pub fn list_groups() -> Result<Vec<MobileGroup>, String> {
    crate::mobile_node::list_groups()
}

/// Load a group's message history (chronological order).
///
/// # Errors
/// Returns an error if the messages cannot be loaded.
pub fn load_group_messages(
    group_id: String,
    limit: i64,
) -> Result<Vec<MobileGroupMessage>, String> {
    crate::mobile_node::load_group_messages(group_id, limit)
}

/// Save an outgoing group message to DB and publish via swarm.
/// `attachment_path`, when present, is stored content-addressedly (files lane
/// §12) and sent as an attachment descriptor on the message.
///
/// # Errors
/// Returns an error if the message cannot be saved, sent, or the attachment
/// stored/read.
pub fn save_outgoing_group(
    group_id: String,
    content: String,
    attachment_path: Option<String>,
) -> Result<MobileGroupMessage, String> {
    crate::mobile_node::save_outgoing_group(group_id, content, attachment_path)
}

/// Accept a pending group invite: materialize the group locally, persist
/// membership, and subscribe to the group's topic so the swarm starts receiving
/// its traffic.
///
/// # Errors
/// Returns an error if the group row cannot be materialized/loaded.
pub fn accept_group_invite(group_id: String) -> Result<MobileGroup, String> {
    crate::mobile_node::accept_group_invite(group_id)
}

/// Leave a group: delete the local rows (messages, membership, the group
/// itself) and unsubscribe from its gossipsub topic. Local-only — public
/// groups have no server-side membership to notify.
///
/// # Errors
/// Returns an error if the group rows cannot be deleted.
pub fn delete_group(group_id: String) -> Result<(), String> {
    crate::mobile_node::delete_group(group_id)
}

/// Set the local user's nickname.
///
/// # Errors
/// Returns an error if the nickname cannot be persisted.
pub fn set_self_nickname(nickname: &str) -> Result<(), String> {
    crate::set_self_nickname(nickname).map_err(|e| e.to_string())
}

/// Set a per-peer local nickname (the name only this install shows for that
/// peer). Validated against the canonical nickname rules
/// ([`validate_nickname`]) so every frontend accepts the same input.
///
/// # Errors
/// Returns an error if the nickname is invalid or cannot be persisted.
pub fn set_peer_local_nickname(peer_id: &str, nickname: &str) -> Result<(), String> {
    if !crate::nickname::validate_nickname(nickname) {
        return Err(format!("invalid nickname: {nickname}"));
    }
    crate::nickname::set_peer_local_nickname(peer_id, nickname).map_err(|e| e.to_string())
}

/// Validate a nickname before persisting it.
///
/// Single source of truth shared with the desktop/TUI path
/// ([`crate::nickname::validate_nickname`]). Exposed so the Flutter UI can
/// reject invalid input without re-implementing the rules in Dart.
#[must_use]
pub fn validate_nickname(nickname: &str) -> bool {
    crate::nickname::validate_nickname(nickname)
}

/// Human-readable network-size class ("Small" / "Medium" / "Large") for a peer
/// count. Mirrors [`crate::network::NetworkSize`] so the Flutter UI doesn't
/// re-derive the thresholds in Dart.
#[must_use]
pub fn network_size_label(peer_count: i64) -> String {
    match peer_count {
        0..=3 => NetworkSize::Small,
        4..=15 => NetworkSize::Medium,
        _ => NetworkSize::Large,
    }
    .to_string()
}

// --- Identity lane ---

/// Resolve this install's user ID from its stored identity and binding.
///
/// Returns `None` until this install's peer ID is bound into some user's
/// device-set ([`crate::identity::DeviceBinding`]).
///
/// # Errors
/// Returns an error if the local peer ID cannot be resolved or the DB lookup
/// fails.
pub fn get_my_user_id() -> Result<Option<String>, String> {
    crate::mobile_api::get_my_user_id()
}

/// Provision this install as a user (account keypair + self-binding claim).
/// The returned string is the new root `user_id`.
///
/// # Errors
/// Returns an error if provisioning fails.
pub fn provision_my_user(
    self_username: Option<String>,
    self_nickname: Option<String>,
) -> Result<String, String> {
    crate::mobile_api::provision_my_user(self_username, self_nickname)
}

/// Send a device-binding `intro` request to a peer over the swarm.
///
/// # Errors
/// Returns an error if the request cannot be queued.
pub fn send_device_binding_intro(peer_id: String) -> Result<(), String> {
    crate::mobile_node::send_device_binding_intro(peer_id)
}

/// Mint a signed claim binding `device_pubkey` at `peer_id` into this
/// install's user, persist the local binding, and send the claim to the device.
///
/// # Errors
/// Returns an error if this install has no user, the claim cannot be minted,
/// or the request cannot be queued.
#[allow(clippy::needless_pass_by_value)]
pub fn accept_device_binding(peer_id: String, device_pubkey: Vec<u8>) -> Result<(), String> {
    // FFI boundary: FRB's Dart `List<int>` only deserializes into an owned
    // `Vec<u8>`; `&[u8]` is unsupported by codegen 2.13.0.
    crate::mobile_node::accept_device_binding(peer_id, &device_pubkey)
}

/// Place an outgoing call: mint a session id, queue its `invite`.
///
/// Returns the fresh `call_id` so the caller can track the session end-to-end
/// (a session ends via [`send_call_signal`] with kind `end`).
///
/// # Errors
/// Returns an error if the request is refused by the running node.
pub fn start_call(peer_id: String) -> Result<String, String> {
    crate::mobile_node::start_call(peer_id)
}

/// Queue a call signal (`accept`/`reject`/`end`) over the calls lane; `call_id`
/// is echoed by every kind and pins the session (mint a fresh one with
/// [`start_call`]).
///
/// # Errors
/// Returns an error if the request is refused by the running node.
pub fn send_call_signal(peer_id: String, call_id: String, kind: String) -> Result<(), String> {
    crate::mobile_node::send_call_signal(peer_id, call_id, kind)
}

/// Verify a raw device-binding claim against the user's stored account key.
///
/// The claim is the raw signature over `user_id ‖ device_pubkey ‖ claim_id`;
/// all three message parts are required to recompute and verify it.
///
/// # Errors
/// Returns an error if the DB lookup fails.
pub fn verify_device_binding_claim(
    user_id: String,
    device_pubkey: Vec<u8>,
    claim_id: String,
    claim: Vec<u8>,
) -> Result<bool, String> {
    crate::mobile_api::verify_device_binding_claim(user_id, device_pubkey, claim_id, claim)
}

/// Verify a claim against the user's account key, then bind the device.
///
/// # Errors
/// Returns an error if the claim fails verification or the insert fails.
pub fn add_device(
    user_id: String,
    peer_id: String,
    device_pubkey: Vec<u8>,
    claim_id: String,
    claim: Vec<u8>,
) -> Result<MobileDeviceInfo, String> {
    crate::mobile_api::add_device(user_id, peer_id, device_pubkey, claim_id, claim)
}

/// List the live devices bound to a user, most recent first.
///
/// # Errors
/// Returns an error if the DB query fails.
pub fn get_user_devices(user_id: String) -> Result<Vec<MobileDeviceInfo>, String> {
    crate::mobile_api::get_user_devices(user_id)
}

/// List this install's user's contacts.
///
/// Returns an empty list before the install is bound to a user.
///
/// # Errors
/// Returns an error if the DB query fails.
pub fn get_contacts() -> Result<Vec<MobileContactInfo>, String> {
    crate::mobile_api::get_contacts()
}

/// Add a contact for this install's user.
///
/// # Errors
/// Returns an error if the install has no bound user or the insert fails.
pub fn add_contact(
    contact_user_id: String,
    nickname_override: Option<String>,
) -> Result<(), String> {
    crate::mobile_api::add_contact(contact_user_id, nickname_override)
}

/// Remove a contact for this install's user.
///
/// # Errors
/// Returns an error if the install has no bound user or the delete fails.
pub fn remove_contact(contact_user_id: String) -> Result<(), String> {
    crate::mobile_api::remove_contact(contact_user_id)
}

/// Load the canonical Contacts-tab roster in a single round trip.
///
/// # Errors
/// Returns an error if the roster cannot be loaded.
pub fn get_contacts_with_stats() -> Result<Vec<MobileContactRow>, String> {
    crate::mobile_api::get_contacts_with_stats()
}

#[cfg(test)]
mod tests {
    use super::*;
    use serial_test::serial;

    fn db_lock() -> std::sync::MutexGuard<'static, ()> {
        crate::db::shared_db_test_lock()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
    }

    #[test]
    #[serial(db)]
    fn set_peer_local_nickname_validates_and_persists() {
        let _guard = db_lock();
        let dir = tempfile::tempdir().expect("tempdir");
        crate::db::reset_db_url();
        crate::mobile_api::init_mobile_database(
            dir.path().join("api.sqlite").to_string_lossy().into_owned(),
        )
        .expect("mobile init");

        // Valid: persisted and readable back through the canonical getter.
        set_peer_local_nickname("peer-1", "alice-1").expect("valid nickname");
        assert_eq!(
            crate::nickname::get_peer_local_nickname("peer-1")
                .expect("read back")
                .as_deref(),
            Some("alice-1")
        );

        // Invalid input is rejected by the same canonical rules everywhere
        // (empty, over the length cap, non-alphanumeric/dash characters).
        for bad in ["", "a-very-long-nickname-over-20", "has space", "bad!"] {
            assert!(
                set_peer_local_nickname("peer-1", bad).is_err(),
                "expected rejection for {bad:?}"
            );
        }
        // A rejected name never overwrites the stored one.
        assert_eq!(
            crate::nickname::get_peer_local_nickname("peer-1")
                .expect("read back")
                .as_deref(),
            Some("alice-1")
        );
    }

    #[test]
    #[serial(db)]
    fn delete_group_removes_group_and_membership() {
        let _guard = db_lock();
        let dir = tempfile::tempdir().expect("tempdir");
        crate::db::reset_db_url();
        crate::mobile_api::init_mobile_database(
            dir.path().join("api.sqlite").to_string_lossy().into_owned(),
        )
        .expect("mobile init");

        let group = crate::groups::create_public_group("Team Rocket").expect("create group");
        crate::groups::record_group_member(&group.group_id, "peer-1").expect("member");
        assert_eq!(
            crate::groups::get_group_member_count(&group.group_id).expect("count"),
            1
        );

        delete_group(group.group_id.clone()).expect("leave group");

        assert!(
            crate::groups::find_group(&group.group_id)
                .expect("lookup")
                .is_none(),
            "group row must be gone"
        );
        assert_eq!(
            crate::groups::get_group_member_count(&group.group_id).expect("count"),
            0,
            "membership must be gone"
        );

        // Unknown group: idempotent success (nothing to delete).
        delete_group("does-not-exist".to_string()).expect("idempotent leave");
    }
}

//! P2P network behavior and protocol definitions

use crate::files::MessageAttachment;
use crate::network::NetworkSize;
use crate::p2plog_debug;
use libp2p::gossipsub;
use libp2p::ping;
use libp2p::request_response;
use libp2p::swarm::NetworkBehaviour;
use serde::{Deserialize, Serialize};

/// Chat protocol name for direct messages
pub const DM_PROTOCOL_NAME: &str = "/p2p-chat/dm/1.0.0";

/// Device-binding protocol name (identity lane §11).
///
/// One-shot signed claims that bind a device (install keypair) into a remote
/// account's device-set. `intro` requests advertise a device+account; `claim`
/// requests carry the account-key-signed claim that the receiver verifies
/// before binding.
pub const DEVICE_BINDING_PROTOCOL_NAME: &str = "/p2p-chat/device-binding/1.0.0";

/// Call-signaling protocol name (calls lane).
///
/// One-shot JSON signals over a dedicated `request_response` lane, mirroring the
/// device-binding pattern. Kinds: `"invite"` (the callee is asked to ring),
/// `"accept"`/`"reject"` (the callee's answer to an invite), and `"end"`
/// (either side tears the call down). The signaling slice carries no media:
/// `CallSignal::descriptor` is reserved for the later offer/answer payload.
pub const CALL_PROTOCOL_NAME: &str = "/p2p-chat/call/1.0.0";

/// File-transfer protocol name (files lane §12).
///
/// A dedicated `request_response` lane for content-addressed attachments. The
/// receiver drives every transfer: it requests the metadata (`"meta"`), then
/// pulls fixed-size chunks (`"chunk"`) sequentially until the file is complete.
/// The sender serves purely from its content-addressed store (prepared by
/// `files::store_outgoing_file` before the message is sent, so the blob is
/// already on disk when the receiver asks).
pub const FILE_TRANSFER_PROTOCOL_NAME: &str = "/p2p-chat/files/1.0.0";

/// Default chat topic
pub const CHAT_TOPIC: &str = "test-net";

/// Direct message content with timestamp and sender info
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct DirectMessage {
    /// The message content/text
    pub content: String,
    /// Unix timestamp when the message was created
    pub timestamp: i64,
    /// Optional timestamp of when the message was sent to the network
    pub sent_at: Option<f64>,
    /// Optional nickname of the sender
    pub nickname: Option<String>,
    /// Optional unique identifier for this message
    pub msg_id: Option<String>,
    /// Optional ID of the message this is acknowledging/replying to
    pub ack_for: Option<String>,
    /// Optional timestamp of when this message was received
    pub received_at: Option<f64>,
    /// Stable `group_id` a private-group DM is attributed to; `None` = plain DM
    pub group_id: Option<String>,
    /// Optional attachment descriptor (files lane §12); the bytes are fetched
    /// separately over the file lane by the receiver.
    pub attachment: Option<MessageAttachment>,
}

/// Broadcast message content with timestamp and sender info
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct BroadcastMessage {
    /// The message content/text
    pub content: String,
    /// Optional timestamp of when the message was sent
    pub sent_at: Option<f64>,
    /// Optional nickname of the sender
    pub nickname: Option<String>,
    /// Optional unique identifier for this message
    pub msg_id: Option<String>,
    /// Optional attachment descriptor (files lane §12)
    pub attachment: Option<MessageAttachment>,
}

/// Group message content traveling over a per-group gossipsub topic
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct GroupMessage {
    /// The group this message belongs to (must match the topic's group id)
    pub group_id: String,
    /// The message content/text
    pub content: String,
    /// Optional timestamp of when the message was sent
    pub sent_at: Option<f64>,
    /// Optional nickname of the sender
    pub nickname: Option<String>,
    /// Optional unique identifier for this message
    pub msg_id: Option<String>,
    /// Optional attachment descriptor (files lane §12)
    pub attachment: Option<MessageAttachment>,
}

/// Backfill request sent on a group's backfill topic on (re)subscribe
/// (backlog §11.5).
///
/// Gossipsub never replays, so a member that was offline — or joined after the
/// group started — misses the gap. On subscribe the member publishes this
/// requesting everything newer than its `after` watermark; **any** online
/// member whose stored history is newer answers by re-publishing the bounded
/// recent messages as ordinary [`GroupMessage`]s on the main group topic, where
/// the `(group_id, msg_id)` unique index (plus the `nil:` synthetic key for
/// messages without an `msg_id`) absorbs every overlap. The request itself is
/// anonymous control traffic — never persisted.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct GroupBackfillRequest {
    /// The group whose gap is being requested (must match the topic's group id).
    pub group_id: String,
    /// Only messages stored with `sent_at` strictly newer than this are asked
    /// for (`0.0` requests the member's full recent history).
    pub after: f64,
}

/// JSON codec for direct message protocol
pub type ChatCodec = libp2p::request_response::json::codec::Codec<DirectMessage, DirectMessage>;

/// File-transfer exchange payload (files lane §12; receiver-driven).
///
/// One wire type, two request `kind`s and one response type:
///
/// * request `"meta"`  — ask for `file_id`'s metadata (name/size/mime/chunking).
/// * request `"chunk"` — pull chunk `chunk_index` of `file_id`.
/// * response         — `kind == "meta"` carries the metadata handshake;
///   `kind == "chunk"` carries `data`; `kind == "error"` carries a `reason`
///   (unknown file, oversized, out-of-range chunk).
///
/// CBOR (not JSON) is used on purpose: chunk payloads are opaque byte strings,
/// which CBOR serializes natively (~1:1) whereas JSON would expand a 1 MiB
/// chunk ~4x into a base64/array text blob.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct FileTransfer {
    /// `"meta"` | `"chunk"`
    pub kind: String,
    /// Content address (SHA-256 hex) of the whole file
    pub file_id: String,
    /// Zero-based chunk index (request `"chunk"` only)
    pub chunk_index: Option<u64>,
}

/// Response to a [`FileTransfer`] request.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct FileTransferResponse {
    /// `"meta"` | `"chunk"` | `"error"`
    pub kind: String,
    /// Content address (SHA-256 hex) of the whole file
    pub file_id: String,
    /// Original filename (`"meta"` only)
    pub name: Option<String>,
    /// Total byte length (`"meta"` only)
    pub size: Option<u64>,
    /// Best-effort MIME type hint (`"meta"` only)
    pub mime: Option<String>,
    /// Number of fixed-size chunks (`"meta"` only; `ceil(size / chunk_size)`)
    pub total_chunks: Option<u64>,
    /// Chunk size in bytes (`"meta"` only)
    pub chunk_size: Option<u64>,
    /// The chunk index echoed back (`"chunk"` only)
    pub chunk_index: Option<u64>,
    /// Raw chunk bytes (`"chunk"` only)
    pub data: Option<Vec<u8>>,
    /// Human-readable failure description (`"error"` only)
    pub reason: Option<String>,
}

/// CBOR codec for the file-transfer protocol
pub type FileTransferCodec =
    libp2p::request_response::cbor::codec::Codec<FileTransfer, FileTransferResponse>;

/// Device-binding exchange payload (identity lane §11; signed claims).
///
/// One wire type, two `kind`s:
///
/// * `"intro"`  — sender advertises its device (and account, once provisioned)
///   so the account holder can decide whether to mint a claim for it.
/// * `"claim"` — a signed device→user claim. `user_id`, `account_pubkey`,
///   `claim_id`, `bound_at` and `signature` are all present. The receiver
///   `save_user`s the root (upsert), verifies `signature` over
///   `user_id ‖ device_pubkey ‖ claim_id` against *that user's* stored account
///   pubkey, and only then binds (`save_device_binding`). Never auto-mints.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct DeviceBindingRequest {
    /// `"intro"` or `"claim"`
    pub kind: String,
    /// Account the claim/intro is about (`None` for an unprovisioned intro)
    pub user_id: Option<String>,
    /// Account pubkey that signs claims for `user_id` (claim; root of trust)
    pub account_pubkey: Option<Vec<u8>>,
    /// Account's self-declared username (display lane)
    pub self_username: Option<String>,
    /// Account's self-declared nickname (display lane)
    pub self_nickname: Option<String>,
    /// Peer ID of the subject device (intro: sender; claim: the device claimed)
    pub peer_id: String,
    /// Pubkey (protobuf) of the subject device (install keypair)
    pub device_pubkey: Vec<u8>,
    /// Unique claim identifier (present on claim)
    pub claim_id: Option<String>,
    /// Unix seconds when the claim was minted (present on claim; display only)
    pub bound_at: Option<f64>,
    /// Signed claim over `user_id ‖ device_pubkey ‖ claim_id` (present on claim)
    pub signature: Option<Vec<u8>>,
}

/// Ack for a device-binding request (`kind` echoes the request kind).
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct DeviceBindingAck {
    /// Whether the exchange was accepted and (for claims) bound
    pub ok: bool,
    /// Human-readable reason on failure
    pub reason: Option<String>,
}

/// JSON codec for the device-binding protocol
pub type DeviceBindingCodec =
    libp2p::request_response::json::codec::Codec<DeviceBindingRequest, DeviceBindingAck>;

/// Call-signaling exchange payload (calls lane; signaling first, media later).
///
/// One wire type, four `kind`s — the caller mints the end-to-end `call_id`
/// (via `gen_msg_id`) and every side echoes it back, so each side can match
/// signals to its live session.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct CallSignal {
    /// `"invite"` | `"accept"` | `"reject"` | `"end"`
    pub kind: String,
    /// Session id minted by the caller; echoed by every later signal.
    pub call_id: String,
    /// Unix seconds when the signal was sent.
    pub timestamp: f64,
    /// Reserved: media offer/answer descriptor (SDP/ICE) when media lands.
    pub descriptor: Option<String>,
}

impl CallSignal {
    /// Build a signal of the given kind for a session, stamping the current
    /// time and leaving the reserved media descriptor empty.
    #[must_use]
    pub fn new(kind: &str, call_id: String) -> Self {
        Self {
            kind: kind.to_string(),
            call_id,
            timestamp: crate::current_timestamp(),
            descriptor: None,
        }
    }
}

/// Ack for a call-signaling request (`ok` = the signal was understood).
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct CallSignalAck {
    /// Whether the signal was accepted
    pub ok: bool,
    /// Human-readable reason on failure
    pub reason: Option<String>,
}

/// JSON codec for the call-signaling protocol
pub type CallSignalCodec = libp2p::request_response::json::codec::Codec<CallSignal, CallSignalAck>;

/// Combined network behavior for p2p chat
#[derive(NetworkBehaviour)]
pub struct AppBehaviour {
    /// Gossipsub protocol handler for broadcast messages
    pub gossipsub: gossipsub::Behaviour,
    /// Request-response protocol handler for direct messages
    pub request_response: request_response::Behaviour<ChatCodec>,
    /// Request-response protocol handler for signed device-binding exchanges
    /// (identity lane §11: intro + account-signed claims)
    pub device_binding: request_response::Behaviour<DeviceBindingCodec>,
    /// Request-response protocol handler for call signaling (calls lane:
    /// invite/accept/reject/end; media transport lands on a later slice)
    pub call_signaling: request_response::Behaviour<CallSignalCodec>,
    /// Request-response protocol handler for content-addressed file transfers
    /// (files lane §12): the receiver pulls metadata and chunks, the sender
    /// serves them from its on-disk store.
    pub file_transfer: request_response::Behaviour<FileTransferCodec>,
    /// mDNS protocol handler for peer discovery (when mdns feature is enabled)
    #[cfg(feature = "mdns")]
    pub mdns: libp2p::mdns::tokio::Behaviour,
    /// Ping protocol for connection liveness: detects dead peers (e.g. a node
    /// that was killed without closing the connection) and closes the
    /// connection so `ConnectionClosed` fires and the peer is marked offline.
    pub ping: ping::Behaviour,
}

// AppBehaviourEvent is auto-generated by the NetworkBehaviour derive macro

/// Build the app behavior with appropriate protocols and configurations
///
/// # Arguments
/// * `key` - libp2p identity keypair
/// * `network_size` - Network size enum for tuning behavior parameters
///
/// # Errors
/// Returns an error if any underlying libp2p protocol behavior fails to build
/// (e.g. an invalid gossipsub configuration or mDNS setup).
pub fn build_behaviour(
    key: &libp2p_identity::Keypair,
    network_size: NetworkSize,
) -> Result<AppBehaviour, String> {
    p2plog_debug(format!(
        "Building behavior for network size: {network_size:?}"
    ));
    // Configure Gossipsub based on network size: larger networks need a longer
    // history and a slower heartbeat to avoid redundant re-broadcasts.
    let (history_gossip, history_length, heartbeat_secs) = match network_size {
        NetworkSize::Small => (3, 20, 1),
        NetworkSize::Medium => (6, 30, 2),
        NetworkSize::Large => (12, 50, 5),
    };
    let gossipsub_config = gossipsub::ConfigBuilder::default()
        .max_transmit_size(262_144)
        .history_gossip(history_gossip)
        .history_length(history_length)
        .heartbeat_interval(std::time::Duration::from_secs(heartbeat_secs))
        .build()
        .map_err(|e| format!("invalid gossipsub config: {e}"))?;

    let gossipsub = gossipsub::Behaviour::new(
        gossipsub::MessageAuthenticity::Signed(key.clone()),
        gossipsub_config,
    )
    .map_err(|e| format!("Failed to create gossipsub behavior: {e}"))?;

    let request_response = request_response::Behaviour::new(
        [(
            libp2p::StreamProtocol::new(DM_PROTOCOL_NAME),
            request_response::ProtocolSupport::Full,
        )],
        request_response::Config::default(),
    );

    let device_binding = request_response::Behaviour::new(
        [(
            libp2p::StreamProtocol::new(DEVICE_BINDING_PROTOCOL_NAME),
            request_response::ProtocolSupport::Full,
        )],
        request_response::Config::default(),
    );

    let call_signaling = request_response::Behaviour::new(
        [(
            libp2p::StreamProtocol::new(CALL_PROTOCOL_NAME),
            request_response::ProtocolSupport::Full,
        )],
        request_response::Config::default(),
    );

    // Chunk payloads ride in the response (cbor default cap: 10 MiB), which
    // comfortably fits one FILE_CHUNK_SIZE chunk plus CBOR overhead; requests
    // (meta/chunk) are tiny. Both sides support Full so any peer can pull.
    let file_transfer = request_response::Behaviour::new(
        [(
            libp2p::StreamProtocol::new(FILE_TRANSFER_PROTOCOL_NAME),
            request_response::ProtocolSupport::Full,
        )],
        request_response::Config::default(),
    );

    // Liveness checks: ping every 10s, treat a missing pong within 10s as a
    // dead connection. This surfaces killed/disconnected peers within ~10-20s
    // instead of waiting on the (often never-elapsed) idle connection timeout.
    let ping = ping::Behaviour::new(
        ping::Config::new()
            .with_interval(std::time::Duration::from_secs(10))
            .with_timeout(std::time::Duration::from_secs(10)),
    );

    #[cfg(feature = "mdns")]
    let mdns = libp2p::mdns::tokio::Behaviour::new(
        libp2p::mdns::Config::default(),
        libp2p::PeerId::from_public_key(&key.public()),
    )
    .map_err(|e| format!("invalid mdns: {e}"))?;

    Ok(AppBehaviour {
        gossipsub,
        request_response,
        device_binding,
        call_signaling,
        file_transfer,
        #[cfg(feature = "mdns")]
        mdns,
        ping,
    })
}

/// Build a fully configured libp2p swarm for chat.
///
/// Sets up TCP (with nodelay), optional QUIC transport, the app behaviour
/// with adaptive network size, and a 60-second idle connection timeout.
///
/// # Errors
/// Returns an error if the libp2p identity cannot be loaded or if the swarm
/// (transport + behaviour) fails to build.
pub fn build_swarm(
    network_size: NetworkSize,
) -> color_eyre::Result<libp2p::swarm::Swarm<AppBehaviour>> {
    use std::time::Duration;

    let key = crate::get_libp2p_identity()?;

    let base = libp2p::SwarmBuilder::with_existing_identity(key)
        .with_tokio()
        .with_tcp(
            libp2p::tcp::Config::default().nodelay(true),
            libp2p::noise::Config::new,
            libp2p::yamux::Config::default,
        )?;

    #[cfg(feature = "quic")]
    let base = base.with_quic();

    let swarm = base
        .with_behaviour(
            |key| -> Result<AppBehaviour, Box<dyn std::error::Error + Send + Sync>> {
                build_behaviour(key, network_size).map_err(
                    |e| -> Box<dyn std::error::Error + Send + Sync> {
                        Box::new(std::io::Error::other(e))
                    },
                )
            },
        )?
        .with_swarm_config(|c| c.with_idle_connection_timeout(Duration::from_mins(1)))
        .build();

    Ok(swarm)
}

