//! Headless CLI binary — minimal footprint, reads from stdin, writes to stderr.

use libp2p::{futures::StreamExt, gossipsub};
use p2p_app::current_timestamp;
use p2p_app::logging::p2plog_info;
use p2p_app::{BroadcastMessage, build_swarm, get_network_size};
use tokio::io::{AsyncBufReadExt as _, BufReader};

enum Event {
    Swarm(Box<libp2p::swarm::SwarmEvent<p2p_app::behavior::AppBehaviourEvent>>),
    Stdin(Option<String>),
}

fn extract_tcp_port(address: &libp2p::Multiaddr) -> Option<i32> {
    address.iter().find_map(|p| match p {
        libp2p::multiaddr::Protocol::Tcp(port) => Some(i32::from(port)),
        _ => None,
    })
}

#[cfg(feature = "quic")]
fn extract_udp_port(address: &libp2p::Multiaddr) -> Option<i32> {
    address.iter().find_map(|p| match p {
        libp2p::multiaddr::Protocol::Udp(port) => Some(i32::from(port)),
        _ => None,
    })
}

fn handle_listen_addr_event(address: &libp2p::Multiaddr) {
    p2p_app::logging::p2plog_info(format!("Listening on: {address}"));
    if let Some(port) = extract_tcp_port(address) {
        let _ = p2p_app::save_listen_ports(Some(port), None);
    }
    #[cfg(feature = "quic")]
    if let Some(port) = extract_udp_port(address) {
        let (tcp, _) = p2p_app::load_listen_ports().unwrap_or((None, None));
        let _ = p2p_app::save_listen_ports(tcp, Some(port));
    }
}

fn handle_message_event(propagation_source: &libp2p::PeerId, message: &gossipsub::Message) {
    let sender = propagation_source.to_string();
    let sender_short = sender.get(..8.min(sender.len())).unwrap_or(&sender);
    let msg_str = String::from_utf8_lossy(&message.data);
    if let Ok(bcast) = serde_json::from_str::<BroadcastMessage>(&msg_str) {
        p2p_app::logging::p2plog_info(format!("[{}] {}", sender_short, bcast.content));
    } else {
        p2p_app::logging::p2plog_info(format!("[{sender_short}] {msg_str}"));
    }
}

#[tokio::main]
async fn main() -> color_eyre::Result<()> {
    color_eyre::install()?;
    p2p_app::logging::init_logging();
    p2plog_info("Starting P2P Chat CLI".to_string());

    // Initialize database once at startup (logs database path and peer ID)
    let _db = p2p_app::init_database()?;

    let network_size = match get_network_size() {
        Ok(size) => {
            p2plog_info(format!("Network size detected: {size:?}"));
            size
        }
        Err(e) => {
            p2plog_info(format!(
                "Could not determine network size, defaulting to Small: {e}"
            ));
            p2p_app::NetworkSize::Small
        }
    };

    let mut swarm = build_swarm(network_size)?;

    let listen_addr: libp2p::Multiaddr = "/ip4/0.0.0.0/tcp/0".parse()?;
    swarm.listen_on(listen_addr)?;

    let topic = gossipsub::IdentTopic::new(p2p_app::CHAT_TOPIC);
    swarm.behaviour_mut().gossipsub.subscribe(&topic)?;

    let stdin = BufReader::new(tokio::io::stdin());
    let mut lines = stdin.lines();

    loop {
        let event = tokio::select! {
            swarm_event = swarm.select_next_some() => Some(Event::Swarm(Box::new(swarm_event))),
            line = lines.next_line() => Some(Event::Stdin(line.ok().flatten())),
        };

        match event {
            Some(Event::Swarm(event)) => match *event {
                libp2p::swarm::SwarmEvent::NewListenAddr { address, .. } => {
                    handle_listen_addr_event(&address);
                }
                libp2p::swarm::SwarmEvent::ConnectionEstablished { peer_id, .. } => {
                    p2p_app::logging::p2plog_info(format!("Connected to: {peer_id} (peers: 1)"));
                }
                libp2p::swarm::SwarmEvent::ConnectionClosed { peer_id, .. } => {
                    p2p_app::logging::p2plog_info(format!("Disconnected from: {peer_id}"));
                }
                libp2p::swarm::SwarmEvent::Behaviour(
                    p2p_app::behavior::AppBehaviourEvent::Gossipsub(
                        libp2p::gossipsub::Event::Message {
                            propagation_source,
                            message,
                            ..
                        },
                    ),
                ) => {
                    handle_message_event(&propagation_source, &message);
                }
                _ => {}
            },
            Some(Event::Stdin(Some(text))) if !text.is_empty() => {
                let msg = BroadcastMessage {
                    content: text,
                    sent_at: Some(current_timestamp()),
                    nickname: None,
                    msg_id: None,
                    attachment: None,
                };
                if let Ok(json) = serde_json::to_string(&msg) {
                    let _ = swarm
                        .behaviour_mut()
                        .gossipsub
                        .publish(topic.clone(), json.as_bytes());
                }
            }
            Some(Event::Stdin(_)) => {}
            None => break,
        }
    }
    Ok(())
}

//! Node server for the web frontend (`docs/web_frontend.md`).
//!
//! Starts the p2p node with the same headless lifecycle as the mobile path
//! (DB selection, identity provisioning, group re-subscription, attachment
//! GC) and then serves the JSON-over-WebSocket API — plus, with `--assets`,
//! the `flutter build web` output — until Ctrl-C.
//!
//! ```text
//! p2p_chat_server [--bind <ip>] [--port <u16>] [--user <name>] \
//!                 [--password <secret>] [--assets <dir>] [--db <sqlite path>]
//! ```
//!
//! Defaults to loopback-only with no credentials (the TUI's trust model).
//! Expose `--bind 0.0.0.0` to other devices only together with HTTP Basic
//! credentials (`--password`, preferably `P2P_WEB_PASSWORD`).

use p2p_app::web::{Credentials, WebConfig};
use std::path::PathBuf;

/// Username the browser's credential dialog must present, unless overridden.
const DEFAULT_USER: &str = "p2p";
/// Preferred way to supply the password: it stays out of `ps` and shell history.
const PASSWORD_ENV: &str = "P2P_WEB_PASSWORD";
const USER_ENV: &str = "P2P_WEB_USER";

const USAGE: &str = "p2p_chat_server — p2p chat node + web frontend API

USAGE:
    p2p_chat_server [OPTIONS]

OPTIONS:
    --bind <ip>        Address to bind (default 127.0.0.1)
    --port <u16>       Port to listen on (default 8080)
    --user <name>      HTTP Basic username (default p2p; env P2P_WEB_USER)
    --password <pw>    HTTP Basic password; enables auth for the API, the
                       WebSocket and the static SPA (env P2P_WEB_PASSWORD —
                       preferred, so the secret stays out of `ps` and shell
                       history). Browsers prompt for these credentials.
    --assets <dir>     Serve a `flutter build web` output directory
    --db <path>        SQLite database path (default: auto-select, same
                       lock-based behavior as the TUI)
    -h, --help         Show this help
";

struct Cli {
    bind: String,
    port: u16,
    user: String,
    password: Option<String>,
    assets: Option<PathBuf>,
    db: Option<String>,
}

/// Parse argv into a [`Cli`]. `Ok(None)` = help was printed.
fn parse_args() -> Result<Option<Cli>, String> {
    let mut cli = Cli {
        bind: "127.0.0.1".to_owned(),
        port: 8080,
        user: std::env::var(USER_ENV)
            .ok()
            .filter(|user| !user.is_empty())
            .unwrap_or_else(|| DEFAULT_USER.to_owned()),
        password: std::env::var(PASSWORD_ENV)
            .ok()
            .filter(|password| !password.is_empty()),
        assets: None,
        db: None,
    };
    let mut args = std::env::args().skip(1);
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "-h" | "--help" => {
                print!("{USAGE}");
                return Ok(None);
            }
            "--bind" => cli.bind = value_of(&arg, &mut args)?,
            "--port" => {
                let raw = value_of(&arg, &mut args)?;
                cli.port = raw
                    .parse()
                    .map_err(|e| format!("invalid --port {raw:?}: {e}"))?;
            }
            "--user" => cli.user = value_of(&arg, &mut args)?,
            "--password" => cli.password = Some(value_of(&arg, &mut args)?),
            "--assets" => cli.assets = Some(PathBuf::from(value_of(&arg, &mut args)?)),
            "--db" => cli.db = Some(value_of(&arg, &mut args)?),
            other => return Err(format!("unknown argument {other:?}\n\n{USAGE}")),
        }
    }
    validate(&cli)?;
    Ok(Some(cli))
}

/// Reject credentials the Basic auth layer could not represent.
fn validate(cli: &Cli) -> Result<(), String> {
    let Some(password) = cli.password.as_deref() else {
        return Ok(());
    };
    if password.is_empty() {
        return Err("--password must not be empty".to_owned());
    }
    if cli.user.is_empty() {
        return Err("--user must not be empty when a password is set".to_owned());
    }
    if cli.user.contains(':') {
        return Err("--user must not contain ':' (RFC 7617 splits on it)".to_owned());
    }
    Ok(())
}

fn value_of(flag: &str, args: &mut impl Iterator<Item = String>) -> Result<String, String> {
    args.next()
        .ok_or_else(|| format!("{flag} requires a value\n\n{USAGE}"))
}

fn main() -> color_eyre::Result<()> {
    color_eyre::install()?;
    let cli = match parse_args() {
        Ok(Some(cli)) => cli,
        Ok(None) => return Ok(()),
        Err(e) => {
            eprintln!("{e}");
            return Err(color_eyre::eyre::eyre!("invalid arguments"));
        }
    };

    let addr: std::net::SocketAddr = format!("{}:{}", cli.bind, cli.port)
        .parse()
        .map_err(|e| color_eyre::eyre::eyre!("invalid --bind/--port: {e}"))?;
    let credentials = cli.password.map(|password| Credentials {
        user: cli.user,
        password,
    });
    if credentials.is_some() && std::env::var_os(PASSWORD_ENV).is_none() {
        eprintln!(
            "NOTE: the password came from the command line, where `ps` and your shell \
             history can see it — prefer {PASSWORD_ENV}."
        );
    }
    if !addr.ip().is_loopback() && credentials.is_none() {
        eprintln!(
            "WARNING: binding non-loopback {addr} without --password — anyone on the network \
             can drive this node (send messages, read history, download attachments)."
        );
    }

    // Start the node on this plain (non-async) thread: the mobile lifecycle
    // builds its own tokio runtime for the swarm, which must not happen
    // inside an async context.
    let peer_id = cli
        .db
        .as_deref()
        .map_or_else(p2p_app::mobile_node::start_node_auto, |db| {
            p2p_app::mobile_node::start_node(db.to_owned())
        })
        .map_err(|e| color_eyre::eyre::eyre!(e))?;

    // Mirror the TUI's console logging: the log callback feeds the in-memory
    // buffer the Log tab polls; also print to stderr for the server console.
    let callback: std::sync::Arc<dyn Fn(String) + Send + Sync> =
        std::sync::Arc::new(|msg| eprintln!("{msg}"));
    p2p_app::logging::register_log_callback(callback);
    eprintln!("p2p chat server online — peer id: {peer_id}");

    let runtime = tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()?;
    runtime
        .block_on(async {
            let served = p2p_app::web::serve(WebConfig {
                bind: addr,
                credentials,
                assets: cli.assets,
            })
            .await;
            // Release the DB lock file on the way out so the next start can pick
            // the same database (mirrors the TUI's shutdown path).
            p2p_app::db::release_db_lock();
            served
        })
        .map_err(|e| color_eyre::eyre::eyre!(e))
}

//! TUI binary — ratatui-based terminal interface and headless fallback entry point.

use std::sync::Arc;

use libp2p::gossipsub;
use p2p_app::build_swarm;
use p2p_app::logging::{init_logging, p2plog_info};

#[cfg(feature = "tui")]
mod tui {
    //! Four-task TUI architecture for `p2p_app`
    //!
    //! ## Overview
    //!
    //! This module implements a concurrent, event-driven terminal UI using async Rust.
    //! Four independent tasks communicate via MPSC channels, each responsible for a specific concern:
    //!
    //! 1. **`SwarmHandler`** - Listens to libp2p network events and translates them to app-level `SwarmEvent`
    //! 2. **`InputHandler`** - Polls terminal for keyboard/mouse input and sends `InputEvent`
    //! 3. **`CommandProcessor`** - Receives `InputEvent` and `SwarmEvent`, mutates `AppState`, sends `SwarmCommand`
    //! 4. **`RenderLoop`** - Reads `AppState` and renders the TUI on demand
    //!
    //! ## Architecture
    //!
    //! ```text
    //! ┌─────────────────────────────────────────────────────┐
    //! │                  libp2p Swarm                       │
    //! └────────────────────────┬────────────────────────────┘
    //!                          │
    //!                          ↓
    //!                  SwarmHandler Task
    //!                    (libp2p events)
    //!                          │
    //!                          ↓ SwarmEvent (mpsc)
    //!          ┌───────────────────────────────┐
    //!          │    CommandProcessor Task      │
    //!          │  ┌─────────────────────────┐  │
    //!          │  │  Shared AppState        │  │
    //!          │  │ (Arc<Mutex<AppState>>)  │  │
    //!          │  └─────────────────────────┘  │
    //!          └───────────────────────────────┘
    //!                 ↑              ↑
    //!    InputEvent   │              │ SwarmEvent
    //!      (mpsc)     │              │ (mpsc)
    //!                 │              │
    //!          InputHandler Task  SwarmHandler Task
    //!                 ↑
    //!          Terminal Input
    //!
    //! RenderLoop continuously reads AppState and redraws terminal.
    //! ```
    //!
    //! ## State Management
    //!
    //! All TUI state is centralized in `AppState` behind an `Arc<Mutex<>>` for safe concurrent access.
    //! Only `CommandProcessor` mutates state; other tasks read-only or signal mutations through channels.
    //!
    //! Channel Capacity: 100 events max in flight per channel (prevents unbounded buffering).
    //!
    //! ## Key Design Decisions
    //!
    //! - **`Arc<Mutex>` over `RwLock`**: Simplicity. Most operations read and modify multiple fields atomically.
    //! - **Polling input instead of event subscriptions**: Works on all platforms with crossterm.
    //! - **Event-driven redraws**: UI updates only when input or network state changes.
    //! - **Immutable channel types**: Each task has dedicated input/output channels, no shared mutable channels.

    pub use p2p_app::tui_tabs::DynamicTabs;
    use ratatui_textarea::TextArea;

    pub mod click_handlers;
    mod command_processor;
    pub mod event_source;
    pub mod input_processor;
    pub mod key_probe;
    pub mod main_loop;
    pub mod message_handlers;
    pub mod render_loop;
    pub mod scroll_handlers;
    pub mod state;
    #[cfg(test)]
    #[path = "../../../tests/unit/unit_bin_tui_test_helpers.rs"]
    pub mod test_helpers;
}

#[tokio::main]
async fn main() -> color_eyre::Result<()> {
    color_eyre::install()?;
    init_logging();
    p2p_app::logging::register_log_callback(Arc::new(|_| p2p_app::logging::request_tui_redraw()));

    // Diagnostic mode: dump raw terminal key bytes so Tab vs Ctrl+I encoding
    // can be inspected per terminal. Runs before any database/network setup.
    if std::env::args().nth(1).as_deref() == Some("key-probe") {
        return tui::key_probe::run();
    }

    // Initialize database once at startup (logs database path and peer ID)
    let _db = p2p_app::init_database()?;

    let topic = gossipsub::IdentTopic::new(p2p_app::CHAT_TOPIC);

    let network_size = match p2p_app::get_network_size() {
        Ok(size) => {
            p2plog_info(format!("Network size detected: {size:?}"));
            size
        }
        Err(e) => {
            p2plog_info(format!(
                "Could not determine network size, defaulting to Small: {e}"
            ));
            p2p_app::NetworkSize::Small
        }
    };

    let mut swarm = build_swarm(network_size)?;

    let listen_addr: libp2p::Multiaddr = "/ip4/0.0.0.0/tcp/0".parse()?;
    swarm.listen_on(listen_addr)?;

    swarm.behaviour_mut().gossipsub.subscribe(&topic)?;

    // Use new 4-task architecture instead of monolithic tokio::select!
    tui::main_loop::run_new_tui(swarm, p2p_app::CHAT_TOPIC.to_string()).await
}

use super::state::AppState;
