    ExpressionMethods, OptionalExtension, QueryDsl, RunQueryDsl as _, SelectableHelper as _,
};

/// Optional metadata for a group message (mirrors [`crate::messages::MessageMeta`]).
#[derive(Default, Clone)]
pub struct GroupMessageMeta {
    /// Optional nickname of the message sender
    pub sender_nickname: Option<String>,
    /// Optional unique identifier for the message
    pub msg_id: Option<String>,
    /// Optional timestamp of when the message was sent
    pub sent_at: Option<f64>,
    /// Optional attachment descriptor (files lane §12)
    pub attachment: Option<crate::files::MessageAttachment>,
}

// ── Topic helpers ──────────────────────────────────────────────────────────

/// Prefix of every per-group gossipsub topic (`group:<group_id>`).
pub const GROUP_TOPIC_PREFIX: &str = "group:";

/// Build the per-group gossipsub topic string for a `group_id`.
#[must_use]
pub fn group_topic(group_id: &str) -> String {
    format!("{GROUP_TOPIC_PREFIX}{group_id}")
}

/// True if `topic` is a per-group topic.
#[must_use]
pub fn is_group_topic(topic: &str) -> bool {
    topic.starts_with(GROUP_TOPIC_PREFIX)
}

/// Extract the group id from a per-group topic string.
#[must_use]
pub fn group_id_from_topic(topic: &str) -> Option<&str> {
    topic.strip_prefix(GROUP_TOPIC_PREFIX)
}

/// Suffix of every per-group backfill topic (`group:<group_id>:backfill`).
///
/// Backfill requests travel on this topic so members can ask for the gap they
/// missed while offline without polluting the main chat topic with control
/// traffic. Answers re-publish real [`GroupMessage`]s on the main group topic.
pub const GROUP_BACKFILL_TOPIC_SUFFIX: &str = ":backfill";

/// Build the per-group backfill gossipsub topic for a `group_id`.
#[must_use]
pub fn group_backfill_topic(group_id: &str) -> String {
    format!("{GROUP_TOPIC_PREFIX}{group_id}{GROUP_BACKFILL_TOPIC_SUFFIX}")
}

/// True if `topic` is a per-group backfill topic.
#[must_use]
pub fn is_backfill_topic(topic: &str) -> bool {
    topic.ends_with(GROUP_BACKFILL_TOPIC_SUFFIX)
}

/// Extract the group id from a backfill topic string.
#[must_use]
pub fn group_id_from_backfill_topic(topic: &str) -> Option<&str> {
    topic
        .strip_prefix(GROUP_TOPIC_PREFIX)
        .and_then(|rest| rest.strip_suffix(GROUP_BACKFILL_TOPIC_SUFFIX))
}

// ── Group identity ─────────────────────────────────────────────────────────

/// Canonical name of a public group: whitespace-trimmed, internal whitespace
/// collapsed, lowercased. Same canonical name == same group everywhere.
#[must_use]
pub fn canonical_group_name(name: &str) -> String {
    name.split_whitespace()
        .map(str::to_lowercase)
        .collect::<Vec<_>>()
        .join(" ")
}

/// Deterministic 64-bit FNV-1-style hash of a string as a `%016x` hex id.
///
/// Stable across platforms and processes (unlike `std`'s random hashers) and
/// hex-only, so derived ids are safe in a gossipsub topic name. Uses only
/// `wrapping_*` method calls (no operator arithmetic, which the crate's clippy
/// config denies).
#[must_use]
fn fnv1a_hex(input: &str) -> String {
    const FNV_OFFSET_BASIS: u64 = 0xcbf2_9ce4_8422_2325;
    const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;
    let mut hash: u64 = FNV_OFFSET_BASIS;
    for byte in input.bytes() {
        hash = hash.wrapping_mul(FNV_PRIME);
        hash = hash.wrapping_add(u64::from(byte));
    }
    format!("{hash:016x}")
}

/// Deterministic 64-bit FNV-1-style hash of the canonical group name as hex.
///
/// Stable across platforms and processes (unlike `std`'s random hashers) and
/// hex-only, so the derived `group_id` is safe in a gossipsub topic name.
#[must_use]
pub fn stable_group_id(name: &str) -> String {
    fnv1a_hex(&canonical_group_name(name))
}

