/// Returns an error if the database query fails.
pub fn get_group_member_count(group_id: &str) -> color_eyre::Result<i64> {
    let conn = &mut crate::sqlite_connect()?;
    group_members::table
        .filter(group_members::group_id.eq(group_id))
        .count()
        .get_result(conn)
