/// Save an outgoing group message (inserted as already-sent: the row only
/// exists because the message was transmitted).
///
/// # Errors
/// Returns an error if the message cannot be inserted.
pub fn save_outgoing_group_message(
    group_id: &str,
    content: &str,
    meta: GroupMessageMeta,
) -> color_eyre::Result<GroupMessage> {
    let conn = &mut crate::sqlite_connect()?;
    let new_msg = NewGroupMessage {
        group_id: group_id.to_string(),
        content: content.to_string(),
        peer_id: None,
        sent: 1,
        msg_id: meta.msg_id,
        sent_at: meta.sent_at,
        sender_nickname: meta.sender_nickname,
        attachment_json: meta
            .attachment
            .as_ref()
            .and_then(crate::files::attachment_to_json),
    };
    diesel::insert_into(group_messages::table)
        .values(&new_msg)
        .returning(GroupMessage::as_returning())
        .get_result(conn)
        .wrap_err("failed to save group message")
}

/// Save an incoming group message, deduplicating mesh re-deliveries on
/// `(group_id, msg_id)`. Returns [`Option::None`] when a duplicate is skipped.
///
/// Messages without an `msg_id` get a stable synthetic key derived from their
/// content, so `SQLite`'s `(group_id, msg_id)` unique index still dedups them —
/// a `NULL` `msg_id` would otherwise slip past the index (`SQLite` treats `NULL`s
/// as distinct) and accept every retransmit.
///
/// # Errors
/// Returns an error if the message cannot be inserted.
pub fn save_incoming_group_message(
    group_id: &str,
    peer_id: &str,
    content: &str,
    meta: GroupMessageMeta,
) -> color_eyre::Result<Option<GroupMessage>> {
    let conn = &mut crate::sqlite_connect()?;
    let msg_id = meta.msg_id.unwrap_or_else(|| {
        let key = fnv1a_hex(&format!(
            "{group_id}|{peer_id}|{}|{content}",
            meta.sent_at.unwrap_or(0.0)
        ));
        format!("nil:{key}")
    });
    let new_msg = NewGroupMessage {
        group_id: group_id.to_string(),
        content: content.to_string(),
        peer_id: Some(peer_id.to_string()),
        sent: 0,
        msg_id: Some(msg_id),
        sent_at: meta.sent_at,
        sender_nickname: meta.sender_nickname,
        attachment_json: meta
            .attachment
            .as_ref()
            .and_then(crate::files::attachment_to_json),
    };
    diesel::insert_into(group_messages::table)
        .values(&new_msg)
        .on_conflict((group_messages::group_id, group_messages::msg_id))
        .do_nothing()
        .returning(GroupMessage::as_returning())
        .get_result(conn)
        .optional()
        .wrap_err("failed to save group message")
}

/// The `sent_at` watermark of a group's newest stored message (`None` when the
/// group has no history).
///
/// Served as the requesting side's `after` boundary for backfill: any member
/// with a *newer* stored message than this was up during the gap and can
/// answer it.
///
/// # Errors
/// Returns an error if the database query fails.
pub fn latest_group_sent_at(group_id: &str) -> color_eyre::Result<Option<f64>> {
    use crate::generated::schema::group_messages;
    let conn = &mut crate::sqlite_connect()?;
    group_messages::table
        .filter(group_messages::group_id.eq(group_id))
        .order_by(group_messages::sent_at.desc())
        .select(group_messages::sent_at)
        .first::<Option<f64>>(conn)
        .optional()
        .wrap_err("failed to read group watermark")
        .map(Option::flatten)
}

/// Load a group's stored messages strictly newer than the `after` watermark,
/// oldest first, bounded to `limit`.
///
/// This is the backfill answer: a member that was up longer than the requester
/// replies by re-publishing exactly these rows on the main group topic, where
/// the requester's `(group_id, msg_id)` unique index (and the `nil:` synthetic
/// key for messages without an `msg_id`) absorbs every overlap. Messages
/// without a `sent_at` are skipped — they predate the watermark convention and
/// any live retransmit dedups them anyway.
///
/// # Errors
/// Returns an error if the database query fails.
pub fn load_group_messages_after(
    group_id: &str,
    after: f64,
    limit: usize,
) -> color_eyre::Result<Vec<GroupMessage>> {
    use crate::generated::schema::group_messages;
    let conn = &mut crate::sqlite_connect()?;
    group_messages::table
        .filter(group_messages::group_id.eq(group_id))
        .filter(group_messages::sent_at.gt(after))
        .order_by(group_messages::sent_at.asc())
        .then_order_by(group_messages::id.asc())
        .limit(crate::usize_limit_to_i64(limit))
        .select(GroupMessage::as_select())
        .load(conn)
        .wrap_err("failed to load backfill history")
}

/// Load a group's messages, newest first, limited to `limit`.
///
/// # Errors
/// Returns an error if the database query fails.
pub fn load_group_messages(group_id: &str, limit: usize) -> color_eyre::Result<Vec<GroupMessage>> {
    let conn = &mut crate::sqlite_connect()?;
    group_messages::table
        .filter(group_messages::group_id.eq(group_id))
        .order_by(group_messages::created_at.desc())
        .then_order_by(group_messages::id.desc())
        .limit(crate::usize_limit_to_i64(limit))
        .select(GroupMessage::as_select())
        .load(conn)
        .wrap_err("failed to load group messages")
}

