//! Pure helper functions for TUI modules that can be unit tested.
//! These functions avoid async state, channels, and external I/O.

use std::collections::{HashMap, VecDeque};
use unicode_width::UnicodeWidthStr;

use crate::PeerRecord;
use crate::types::{StringMap, StringSet};

/// Sort peers by last seen time (descending)
pub fn sort_peers_by_last_seen(
    peers: &mut VecDeque<PeerRecord>,
    current_selection: usize,
) -> usize {
    let selected_peer_id = peers.get(current_selection).map(|p| p.peer_id.clone());

    let mut peers_vec: Vec<_> = peers.drain(..).collect();
    peers_vec.sort_by(|a, b| b.last_seen.cmp(&a.last_seen));
    *peers = peers_vec.into();

    selected_peer_id.map_or_else(
        || current_selection.min(peers.len().saturating_sub(1)),
        |sel_id| {
            peers
                .iter()
                .position(|p| p.peer_id == sel_id)
                .unwrap_or(0)
                .min(peers.len().saturating_sub(1))
        },
    )
}

/// Insert or update peer last seen time
pub fn upsert_peer_last_seen(
    peers: &mut VecDeque<PeerRecord>,
    current_selection: usize,
    peer_id: &str,
    seen_at: &str,
) -> usize {
    if let Some(p) = peers.iter_mut().find(|p| p.peer_id == peer_id) {
        p.last_seen = seen_at.to_string();
    } else {
        peers.push_back(PeerRecord {
            peer_id: peer_id.to_string(),
            first_seen: seen_at.to_string(),
            last_seen: seen_at.to_string(),
        });
    }
    sort_peers_by_last_seen(peers, current_selection)
}

// ============================================
// Scroll handler pure functions
// ============================================

/// Default page size for scrolling
pub const PAGE_SIZE: usize = 8;

/// Default wheel scroll lines
pub const WHEEL_SCROLL_LINES: usize = 3;

/// Disables auto-scroll and sets offset to max if auto-scroll was enabled
pub const fn disable_auto_scroll_to_max(
    auto_scroll: &mut bool,
    scroll_offset: &mut usize,
    max_offset: usize,
) {
    if *auto_scroll {
        *auto_scroll = false;
        *scroll_offset = max_offset;
    }
}

/// Scroll up by one line or page
pub const fn scroll_up_lines(scroll_offset: &mut usize, lines: usize) {
    *scroll_offset = scroll_offset.saturating_sub(lines);
}

/// Scroll down to target, enabling auto-scroll if reaching max
pub const fn scroll_down_lines(
    scroll_offset: &mut usize,
    auto_scroll: &mut bool,
    lines: usize,
    max_offset: usize,
) {
    let candidate = scroll_offset.saturating_add(lines);
    *scroll_offset = if candidate < max_offset {
        candidate
    } else {
        max_offset
    };
    if *scroll_offset >= max_offset {
        *auto_scroll = true;
    }
}

/// Convert crossterm `KeyCode` to scroll action string
#[must_use]
pub const fn key_code_to_scroll_action(
    key_code: crossterm::event::KeyCode,
) -> Option<&'static str> {
    match key_code {
        crossterm::event::KeyCode::Up => Some("Up"),
        crossterm::event::KeyCode::Down => Some("Down"),
        crossterm::event::KeyCode::PageUp => Some("PageUp"),
        crossterm::event::KeyCode::PageDown => Some("PageDown"),
        crossterm::event::KeyCode::Home => Some("Home"),
        crossterm::event::KeyCode::End => Some("End"),
        _ => None,
    }
}

/// Handle scroll key for a section - returns new (`scroll_offset`, `auto_scroll`)
#[must_use]
pub fn handle_scroll_key_for_section(
    key_code: &str,
    scroll_offset: usize,
    auto_scroll: bool,
    max_offset: usize,
) -> (usize, bool) {
    let mut new_offset = scroll_offset;
    let mut new_auto = auto_scroll;

    match key_code {
        "Up" => {
            disable_auto_scroll_to_max(&mut new_auto, &mut new_offset, max_offset);
            scroll_up_lines(&mut new_offset, 1);
        }
        "Down" => {
            disable_auto_scroll_to_max(&mut new_auto, &mut new_offset, max_offset);
            scroll_down_lines(&mut new_offset, &mut new_auto, 1, max_offset);
        }
        "PageUp" => {
            disable_auto_scroll_to_max(&mut new_auto, &mut new_offset, max_offset);
            scroll_up_lines(&mut new_offset, PAGE_SIZE);
        }
        "PageDown" => {
            disable_auto_scroll_to_max(&mut new_auto, &mut new_offset, max_offset);
            scroll_down_lines(&mut new_offset, &mut new_auto, PAGE_SIZE, max_offset);
        }
        "Home" => {
            new_auto = false;
            new_offset = 0;
        }
        "End" => {
            new_auto = true;
            new_offset = max_offset;
        }
        _ => {}
    }
    (new_offset, new_auto)
}

/// Rename sender labels in a DM transcript when a nickname changes.
///
/// Replaces all occurrences of `[old_nick] ` with `[new_nick] ` so the
/// conversation history stays consistent after a nickname update.
pub fn relabel_dm_transcript(
    messages: &mut std::collections::VecDeque<String>,
    old_nick: &str,
    new_nick: &str,
) {
    let from = format!("[{old_nick}] ");
    let to = format!("[{new_nick}] ");
    for line in messages.iter_mut() {
        if line.contains(&from) {
            *line = line.replace(&from, &to);
        }
    }
}

/// Abstraction over the per-peer direct-message map so the peers table can be
/// built from either a `HashMap` (the app state) or a `BTreeMap` (the render state).
pub trait PeerMessageMap {
    /// Number of direct messages stored for `peer_id`.
    fn dm_count_for(&self, peer_id: &str) -> usize;
}

impl PeerMessageMap for StringMap<VecDeque<String>> {
    fn dm_count_for(&self, peer_id: &str) -> usize {
        self.get(peer_id).map_or(0, VecDeque::len)
    }
}

impl PeerMessageMap for std::collections::BTreeMap<String, VecDeque<String>> {
    fn dm_count_for(&self, peer_id: &str) -> usize {
        self.get(peer_id).map_or(0, VecDeque::len)
    }
}

/// A single row of the peers table, mirroring Flutter's peer list.
pub struct PeerTableRow {
    pub peer_id: String,
    pub display_name: String,
    pub dm_count: usize,
    pub broadcast_count: usize,
    pub last_seen: String,
    pub first_seen: String,
}

/// Marker filling the DM/broadcast cells of a device sub-row: per-device
/// message stats are not tracked (they're aggregated at the contact level), so
/// those cells render a dash instead of a number.
pub const DEVICE_ROW_STATS_MARKER: usize = usize::MAX;

/// Format a peers-table count cell, rendering a dash for a device sub-row's
/// unknown (unaggregated) DM/broadcast stats.
#[must_use]
pub fn peer_count_display(count: usize) -> String {
    if count == DEVICE_ROW_STATS_MARKER {
        "\u{2013}".to_string()
    } else {
        count.to_string()
    }
}

impl PeerTableRow {
    #[must_use]
    pub fn new(
        peer_id: &str,
        display_name: &str,
        dm_count: usize,
        broadcast_count: usize,
        last_seen: &str,
        first_seen: &str,
    ) -> Self {
        Self {
            peer_id: peer_id.to_string(),
            display_name: display_name.to_string(),
            dm_count,
            broadcast_count,
            last_seen: last_seen.to_string(),
            first_seen: first_seen.to_string(),
        }
    }
}

/// Build and sort the peers table according to the active column and order.
///
/// Mirrors Flutter's peer-list sort. Columns: name (0), DM count (1),
/// broadcast count (2), last seen (3), first seen (4). The tie-breaker is
/// always the peer id to keep the ordering stable.
///
/// `broadcast_sent_to_peer` maps a peer id to how many broadcasts *we* sent that
/// peer (from the `broadcast_recipients` table via `messages::get_all_peer_stats`).
#[must_use]
pub fn sort_peers_table(
    peers: &[PeerRecord],
    dm_messages: &impl PeerMessageMap,
    broadcast_sent_to_peer: &StringMap<usize>,
    sort_column: usize,
    ascending: bool,
) -> Vec<PeerTableRow> {
    let mut rows: Vec<(PeerTableRow, String)> = peers
        .iter()
        .map(|p| {
            let row = peer_table_row(p, dm_messages, broadcast_sent_to_peer);
            let name_key = row.display_name.to_lowercase();
            (row, name_key)
        })
        .collect();

    rows.sort_by(|(a, an), (b, bn)| {
        let ord = match sort_column {
            0 => {
                if an == bn {
                    a.peer_id.cmp(&b.peer_id)
                } else {
                    an.cmp(bn)
                }
            }
            1 => a
                .dm_count
                .cmp(&b.dm_count)
                .then_with(|| a.peer_id.cmp(&b.peer_id)),
            2 => a
                .broadcast_count
                .cmp(&b.broadcast_count)
                .then_with(|| a.peer_id.cmp(&b.peer_id)),
            3 => crate::fmt::parse_last_seen_ms(&a.last_seen)
                .cmp(&crate::fmt::parse_last_seen_ms(&b.last_seen))
                .then_with(|| a.peer_id.cmp(&b.peer_id)),
            _ => crate::fmt::parse_last_seen_ms(&a.first_seen)
                .cmp(&crate::fmt::parse_last_seen_ms(&b.first_seen))
                .then_with(|| a.peer_id.cmp(&b.peer_id)),
        };
        if ascending { ord } else { ord.reverse() }
    });
    rows.into_iter().map(|(row, _)| row).collect()
}

/// Reorder `peers` in place according to the active column/order, preserving
/// the currently selected peer (by id) and returning its new index.
#[must_use]
pub fn sort_peers_by_column(
    peers: &mut VecDeque<PeerRecord>,
    dm_messages: &impl PeerMessageMap,
    broadcast_sent_to_peer: &StringMap<usize>,
    sort_column: usize,
    ascending: bool,
    selection: usize,
) -> usize {
    let selected_id = peers.get(selection).map(|p| p.peer_id.clone());
    // Collect the whole list up front: `peers.as_slices().0` would only cover
    // the first backing slice when the `VecDeque` has wrapped around.
    let all: Vec<PeerRecord> = peers.iter().cloned().collect();
    let rows = sort_peers_table(
        &all,
        dm_messages,
        broadcast_sent_to_peer,
        sort_column,
        ascending,
    );
    // Index rows by peer id so reordering is O(n) instead of a per-row scan.
    let ordered = {
        let by_id: HashMap<&str, PeerRecord> = all
            .iter()
            .map(|p| (p.peer_id.as_str(), p.clone()))
            .collect();
        rows.iter()
            .filter_map(|r| by_id.get(r.peer_id.as_str()).cloned())
            .collect::<VecDeque<PeerRecord>>()
    };
    *peers = ordered;
    selected_id
        .and_then(|id| peers.iter().position(|p| p.peer_id == id))
        .unwrap_or(0)
}

/// Build a single peers-table row, including the display-name lookup.
fn peer_table_row(
    peer: &PeerRecord,
    dm_messages: &impl PeerMessageMap,
    broadcast_sent_to_peer: &HashMap<String, usize>,
) -> PeerTableRow {
    let dm_count = dm_messages.dm_count_for(&peer.peer_id);
    let broadcast_count = broadcast_sent_to_peer
        .get(&peer.peer_id)
        .copied()
        .unwrap_or(0);
    let display_name = crate::get_peer_display_name_or_short(&peer.peer_id);
    PeerTableRow::new(
        &peer.peer_id,
        &display_name,
        dm_count,
        broadcast_count,
        &peer.last_seen,
        &peer.first_seen,
    )
}

/// Build table rows for the contiguous `[start, end)` slice of `peers`.
///
/// Only peers inside the visible window get a `PeerTableRow`, so paged
/// rendering pays for the display-name lookups on the visible page instead of
/// the whole peer list.
#[must_use]
pub fn peer_table_rows_range(
    peers: &[PeerRecord],
    dm_messages: &impl PeerMessageMap,
    broadcast_sent_to_peer: &StringMap<usize>,
    start: usize,
    end: usize,
) -> Vec<PeerTableRow> {
    peers
        .iter()
        .skip(start)
        .take(end.saturating_sub(start))
        .map(|p| peer_table_row(p, dm_messages, broadcast_sent_to_peer))
        .collect()
}

/// One selectable row of the flattened Contacts table.
///
/// The Contacts tab renders one row per contact plus, while a multi-device
/// contact is expanded, one row per device below it. Cursors, clicks, and the
/// scrolling viewport all index into this flattened plan.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ContactTableRowRef {
    /// The contact row itself (index into the sorted contact list).
    Contact(usize),
    /// The `device_idx`-th device of contact `contact_idx`.
    Device {
        contact_idx: usize,
        device_idx: usize,
    },
}

impl ContactTableRowRef {
    /// The peer ID this row targets: the contact's best device, or the exact
    /// device of a device row.
    #[must_use]
    pub fn peer_id(self, contacts: &[crate::contacts::ContactRow]) -> Option<&str> {
        match self {
            Self::Contact(idx) => contacts
                .get(idx)
                .and_then(crate::contacts::ContactRow::best_device_peer_id),
            Self::Device {
                contact_idx,
                device_idx,
            } => contacts
                .get(contact_idx)
                .and_then(|c| c.device_rows.get(device_idx))
                .map(|d| d.peer_id.as_str()),
        }
    }

    /// The contact ID owning this row (used to preserve the selection across
    /// re-sorts, where a device selection collapses onto its contact row).
    #[must_use]
    pub fn contact_id(self, contacts: &[crate::contacts::ContactRow]) -> Option<&str> {
        let idx = match self {
            Self::Contact(idx) => idx,
            Self::Device { contact_idx, .. } => contact_idx,
        };
        contacts.get(idx).map(|c| c.contact_id.as_str())
    }
}

/// Flatten the Contacts table into its selectable rows, in display order.
///
/// Each contact contributes its own row; an expanded multi-device contact
/// contributes its device rows immediately below. Contact rows keep their
/// sorted order, so the plan inherits the current sort.
#[must_use]
pub fn contact_table_plan(
    contacts: &[crate::contacts::ContactRow],
    expanded: &StringSet,
) -> Vec<ContactTableRowRef> {
    let mut plan = Vec::with_capacity(contacts.len());
    for (contact_idx, contact) in contacts.iter().enumerate() {
        plan.push(ContactTableRowRef::Contact(contact_idx));
        if expanded.contains(&contact.contact_id) {
            plan.extend((0..contact.device_rows.len()).map(|device_idx| {
                ContactTableRowRef::Device {
                    contact_idx,
                    device_idx,
                }
            }));
        }
    }
    plan
}

/// Number of selectable rows in the flattened Contacts table.
#[must_use]
pub fn contact_table_plan_len(
    contacts: &[crate::contacts::ContactRow],
    expanded: &StringSet,
) -> usize {
    contact_table_plan(contacts, expanded).len()
}

/// Map a canonical contact row to a peers-table row.
///
/// The Contacts tab renders through the same 5-column `PeerTableRow` layout as
/// the old peer list so windowing, widths, and header-click geometry stay
/// shared. Multi-device contacts prefix an expand marker (`▸` collapsed, `▾`
/// expanded) and append their device count (`"×N"`); sorting is unaffected
/// because it happens on the contact rows themselves before this mapping.
#[must_use]
pub fn contact_to_peer_table_row(
    contact: &crate::contacts::ContactRow,
    expanded: bool,
) -> PeerTableRow {
    let display_name = if contact.device_count > 1 {
        format!(
            "{} {} \u{00d7}{}",
            if expanded { "\u{25be}" } else { "\u{25b8}" },
            contact.display_name,
            contact.device_count
        )
    } else {
        contact.display_name.clone()
    };
    PeerTableRow::new(
        &contact.contact_id,
        &display_name,
        usize::try_from(contact.dm_count).unwrap_or(0),
        usize::try_from(contact.broadcast_sent_to_peer).unwrap_or(0),
        &contact.last_seen,
        &contact.first_seen,
    )
}

/// Build the peers-table row for one flattened entry: contact rows carry the
/// aggregate cells, device rows show the device's own seen times under an
/// indented name with a dash in the DM/broadcast cells.
///
/// `expanded` marks the target contact's own row as expanded, so its expand
/// marker is drawn collapsed or expanded to match the plan.
#[must_use]
pub fn contact_table_row(
    contacts: &[crate::contacts::ContactRow],
    expanded: &StringSet,
    row: ContactTableRowRef,
) -> PeerTableRow {
    match row {
        ContactTableRowRef::Contact(idx) => {
            let Some(contact) = contacts.get(idx) else {
                return PeerTableRow::new("", "", 0, 0, "", "");
            };
            contact_to_peer_table_row(
                contact,
                expanded.contains(&contact.contact_id) && contact.device_count > 1,
            )
        }
        ContactTableRowRef::Device {
            contact_idx,
            device_idx,
        } => {
            let Some(contact) = contacts.get(contact_idx) else {
                return PeerTableRow::new("", "", 0, 0, "", "");
            };
            let Some(device) = contact.device_rows.get(device_idx) else {
                return PeerTableRow::new("", "", 0, 0, "", "");
            };
            PeerTableRow::new(
                &device.peer_id,
                &format!("  {}", device.display_name),
                DEVICE_ROW_STATS_MARKER,
                DEVICE_ROW_STATS_MARKER,
                &device.last_seen,
                &device.first_seen,
            )
        }
    }
}

/// Build table rows for the contiguous `[start, end)` slice of the flattened
/// Contacts table (contacts plus any expanded device rows).
#[must_use]
pub fn contact_table_rows_range(
    contacts: &[crate::contacts::ContactRow],
    expanded: &StringSet,
    start: usize,
    end: usize,
) -> Vec<PeerTableRow> {
    let plan = contact_table_plan(contacts, expanded);
    plan.iter()
        .skip(start)
        .take(end.saturating_sub(start))
        .map(|&row| contact_table_row(contacts, expanded, row))
        .collect()
}

/// Visible window `(start, end)` of the peers table for the given cursor model.
///
/// This mirrors ratatui's `Table::visible_rows` for single-line rows: the
/// window begins at `offset` (clamped to the last row, never after the
/// selection), fills down to `page_height` rows, then scrolls page-by-page
/// until the selected row is on screen, and finally includes a trailing
/// partial row if space remains.
#[must_use]
pub fn peer_table_visible_range(
    offset: usize,
    selected: Option<usize>,
    total_rows: usize,
    page_height: usize,
) -> (usize, usize) {
    if total_rows == 0 {
        return (0, 0);
    }
    let page_height = page_height.max(1_usize);
    let last_row = total_rows.saturating_sub(1);
    let mut start = selected.map_or(offset, |sel| offset.min(sel)).min(last_row);
    let mut end = start;
    let mut height: usize = 0;
    for _ in start..total_rows {
        if height.saturating_add(1) > page_height {
            break;
        }
        height = height.saturating_add(1);
        end = end.saturating_add(1);
    }
    if let Some(sel) = selected {
        let sel = sel.min(last_row);
        while sel >= end {
            height = height.saturating_add(1);
            end = end.saturating_add(1);
            while height > page_height {
                height = height.saturating_sub(1);
                start = start.saturating_add(1);
            }
        }
    }
    if height < page_height && end < total_rows {
        end = end.saturating_add(1);
    }
    (start, end)
}

/// Sort-direction indicator shown on the active peers-table column header.
#[must_use]
pub const fn peer_sort_indicator(ascending: bool) -> &'static str {
    if ascending { " ▲" } else { " ▼" }
}

/// Header labels for the peers table; the sort indicator marks the active column.
#[must_use]
pub fn peer_table_header_labels(sort_column: usize, sort_ascending: bool) -> Vec<String> {
    const COLUMNS: [&str; 5] = ["Name", "DM", "Broadcast", "Last Seen", "First Seen"];
    let indicator = peer_sort_indicator(sort_ascending);
    COLUMNS
        .iter()
        .enumerate()
        .map(|(i, name)| {
            if i == sort_column {
                format!("{name}{indicator}")
            } else {
                (*name).to_string()
            }
        })
        .collect()
}

/// Display width of each cell of a peers-table row (CJK/wide chars = 2 cols).
#[must_use]
fn peer_cell_widths(row: &PeerTableRow) -> [usize; 5] {
    [
        row.display_name.width(),
        peer_count_display(row.dm_count).width(),
        peer_count_display(row.broadcast_count).width(),
        row.last_seen.width(),
        row.first_seen.width(),
    ]
}

/// Render widths for the peers-table columns.
///
/// Each column is exactly wide enough for its longest header (including the
/// sort indicator) or cell, so the table only spans its content instead of
/// filling the whole area.
#[must_use]
pub fn peer_table_column_widths(
    rows: &[PeerTableRow],
    sort_column: usize,
    sort_ascending: bool,
) -> Vec<usize> {
    let mut widths: Vec<usize> = peer_table_header_labels(sort_column, sort_ascending)
        .iter()
        .map(|h| h.width())
        .collect();
    for row in rows {
        for (slot, cell) in widths.iter_mut().zip(peer_cell_widths(row)) {
            *slot = (*slot).max(cell);
        }
    }
    widths
}

