    /// Peer ID of the sender, or `None` if sent by the local user.
    pub sender_peer_id: Option<String>,
}

/// Peer record with identification and timestamps.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct PeerRecord {
    /// The peer's libp2p peer ID.
    pub peer_id: String,
    /// Timestamp (RFC 3339) when this peer was first seen.
    pub first_seen: String,
    /// Timestamp (RFC 3339) when this peer was last seen.
    pub last_seen: String,
}

impl std::fmt::Display for PeerRecord {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{} ({})", self.peer_id, self.last_seen)
    }
}

/// Data common to both broadcast and direct messages from the swarm
#[derive(Debug, Clone)]
pub struct MessageEvent {
    /// The message text
    pub content: String,
    /// Sender's peer ID
    pub peer_id: String,
    /// Round-trip latency string, if known
    pub latency: Option<String>,
    /// Sender's nickname, if provided
    pub nickname: Option<String>,
    /// Unique message ID, if present
    pub msg_id: Option<String>,
    /// Attachment descriptor, if the message carries a file (files lane §12)
    pub attachment: Option<crate::files::MessageAttachment>,
}

/// A group message received from a peer over a per-group gossipsub topic
#[derive(Debug, Clone)]
pub struct GroupMessageEvent {
    /// The group this message belongs to
    pub group_id: String,
    /// The message text
    pub content: String,
    /// Sender's peer ID
    pub peer_id: String,
    /// Sender's nickname, if provided
    pub nickname: Option<String>,
    /// Unique message ID, if present
    pub msg_id: Option<String>,
    /// Attachment descriptor, if the message carries a file (files lane §12)
    pub attachment: Option<crate::files::MessageAttachment>,
}

/// High-level application events from the swarm
#[derive(Debug, Clone)]
pub enum SwarmEvent {
    /// Broadcast message received from peer
    BroadcastMessage(MessageEvent),
    /// Direct message received from peer
    DirectMessage(MessageEvent),
    /// Group message received from a peer
    GroupMessage(GroupMessageEvent),
    /// Invitation to join a private group the local peer does not yet belong to
    GroupInvite {
        /// The group we are being invited to
        group_id: String,
        /// Peer ID of the peer extending the invitation
        inviter_peer: String,
    },
    /// Receipt confirmation received from a peer (for either broadcast or direct messages).
    Receipt {
        /// Peer ID of the sender who acknowledged the message
        peer_id: String,
        /// Message ID this receipt is acknowledging
        ack_for: String,
        /// Timestamp (seconds since epoch) when the peer received the message
        received_at: Option<f64>,
    },
    /// Peer connected to the network
    PeerConnected(String),
    /// Peer disconnected from the network
    PeerDisconnected(String),
    /// Local address established for listening
    ListenAddrEstablished(String),
    /// Peer discovered via mDNS
    #[cfg(feature = "mdns")]
    PeerDiscovered {
        /// Discovered peer's ID
        peer_id: String,
        /// Addresses at which the peer can be reached
        addresses: Vec<Multiaddr>,
    },
    /// Peer expired via mDNS
    #[cfg(feature = "mdns")]
    PeerExpired {
        /// Expired peer's ID
        peer_id: String,
    },
    /// A peer advertised its device (and optionally its account) via the
    /// device-binding protocol (identity lane §11). Surfaced so the operator
    /// can decide whether to mint a signed claim for that device.
    DeviceBindingIntro {
        /// Peer ID of the advertising device
        peer_id: String,
        /// Pubkey (protobuf) of the advertising device's install keypair
        device_pubkey: Vec<u8>,
    },
    /// A signed device-binding claim for **our** device was accepted by the
    /// account holder (identity lane §11): our install's peer ID is now bound
    /// into that user's device-set.
    DeviceBindingReceived {
        /// The account our device was just bound into
        user_id: String,
    },
    /// An incoming call invite (calls lane). The `call_id` is minted by the
    /// caller and must be echoed back in the accept/reject/end signals.
    CallInvite {
        /// End-to-end session id minted by the caller
        call_id: String,
        /// Peer ID of the caller
        peer_id: String,
    },
    /// Our outgoing invite was accepted: the call is live from our side.
    CallAccepted {
        /// Session id echoed back by the callee
        call_id: String,
        /// Peer ID of the callee
        peer_id: String,
    },
    /// Our outgoing invite was declined.
    CallRejected {
        /// Session id echoed back by the callee
        call_id: String,
        /// Peer ID of the callee
        peer_id: String,
    },
    /// A call was torn down (either side sent "end"). Both sides transition
    /// their session to `Ended`.
    CallEnded {
        /// Session id of the ended call
        call_id: String,
        /// Peer ID the call was with
        peer_id: String,
    },
    /// An inbound attachment finished downloading (files lane §12). The message
    /// it rode on was already delivered; this fires when the bytes are stored
    /// and verifiable, so frontends can refresh their chip status/open affordance.
    FileReceived {
        /// Peer the file was pulled from
        peer_id: String,
        /// Content address (SHA-256 hex) of the stored file
        file_id: String,
        /// Original filename
        name: String,
        /// Absolute path of the stored blob
        path: String,
    },
}

/// Commands sent to the swarm task
#[derive(Debug, Clone)]
pub enum SwarmCommand {
    /// Publish a message to the broadcast topic
    Publish {
        /// The message text to broadcast
        content: String,
        /// Optional sender nickname to include in the message
        nickname: Option<String>,
        /// Optional unique message ID
        msg_id: Option<String>,
        /// Optional attachment descriptor (files lane §12); the sender already
        /// staged the bytes with `files::store_outgoing_file`.
        attachment: Option<crate::files::MessageAttachment>,
    },
    /// Send a direct message to a peer
    SendDm {
        /// Recipient's peer ID
        peer_id: String,
        /// The message text
        content: String,
        /// Optional sender nickname
        nickname: Option<String>,
        /// Optional unique message ID
        msg_id: Option<String>,
        /// Optional ID of the message this is acknowledging
        ack_for: Option<String>,
        /// Optional attachment descriptor (files lane §12)
        attachment: Option<crate::files::MessageAttachment>,
    },
    /// Publish a message to a group's per-group gossipsub topic
    PublishGroup {
        /// The group to send to
        group_id: String,
        /// The message text
        content: String,
        /// Optional sender nickname
        nickname: Option<String>,
        /// Optional unique message ID
        msg_id: Option<String>,
        /// Optional attachment descriptor (files lane §12)
        attachment: Option<crate::files::MessageAttachment>,
    },
    /// Subscribe to a group's per-group gossipsub topic
    SubscribeGroup {
        /// The group to join
        group_id: String,
    },
    /// Unsubscribe from a group's per-group gossipsub topic
    UnsubscribeGroup {
        /// The group to leave
        group_id: String,
    },
    /// Send a device-binding request (intro or signed claim) to a peer over the
    /// dedicated request-response protocol (identity lane §11).
    SendDeviceBinding {
        /// The peer to send the request to
        peer_id: String,
        /// The device-binding payload to transmit (boxed: keeps this variant
        /// near the others so the command channel stays small)
        request: Box<crate::behavior::DeviceBindingRequest>,
    },
    /// Send a call-signaling request to a peer over the dedicated
    /// request-response lane (calls lane: invite/accept/reject/end).
    SendCallSignal {
        /// The peer to send the signal to
        peer_id: String,
        /// The call-signaling payload (boxed: keeps the command channel small)
        signal: Box<crate::behavior::CallSignal>,
    },
}

/// Maximum broadcast messages to keep in memory (older messages are dropped).
pub const MAX_MESSAGE_HISTORY: usize = 1000;
/// Maximum direct messages to keep per peer conversation.
pub const MAX_DM_HISTORY: usize = 1000;

//! JSON method dispatch for the web frontend (`docs/web_frontend.md`).
//!
//! One arm per FRB-exposed function; method names mirror the Dart-side FRB
//! names so `HttpNodeApi` is a mechanical mapping. Every arm runs on a
//! `spawn_blocking` worker (see `super::answer_frame`), so the sync DB calls
//! behave exactly like they do under FRB's thread pool.
//!
//! [`dispatch`] routes by method name to a domain sub-dispatcher; a method
//! reaching a domain that doesn't own it is a routing bug and yields an
//! explicit error rather than a panic (panics are denied crate-wide).

use crate::api;
use crate::mobile_api;
use crate::mobile_node;
use serde::Serialize;
use serde::de::DeserializeOwned;
use serde_json::Value;

/// Run one method. `params` is the frame's `params` payload (`Null` when
/// absent).
///
/// # Errors
/// Returns the method's error string (mirrors the `Result<_, String>` shape
/// of the FRB surface), a parameter-parse error, or "unknown method".
pub fn dispatch(method: &str, params: Value) -> Result<Value, String> {
    match method {
        m @ ("getMobilePeerStatus"
        | "startNode"
        | "startNodeAuto"
        | "stopNode"
        | "getLogs"
        | "clearLogs"
        | "getKnownPeers"
        | "getPeersWithStats"
        | "sortPeers") => node_state(m, params),
        m @ ("loadBroadcastMessages"
        | "loadDmMessages"
        | "saveOutgoingBroadcast"
        | "saveOutgoingDm"
        | "saveIncomingMessage") => messages(m, params),
        m @ ("createGroup" | "listGroups" | "loadGroupMessages" | "saveOutgoingGroup"
        | "acceptGroupInvite" | "deleteGroup") => groups(m, params),
        m @ ("setSelfNickname"
        | "setPeerLocalNickname"
        | "validateNickname"
        | "networkSizeLabel"
        | "getMyUserId"
        | "provisionMyUser"
        | "sendDeviceBindingIntro"
        | "acceptDeviceBinding"
        | "verifyDeviceBindingClaim"
        | "addDevice"
        | "getUserDevices") => identity(m, params),
        m @ ("getContacts"
        | "addContact"
        | "removeContact"
        | "getContactsWithStats"
        | "sortContacts"
        | "startCall"
        | "sendCallSignal") => contacts_calls(m, params),
        m @ ("formatTimeHhmm" | "isAtBottom" | "parseLastSeenMs") => ui_helpers(m, params),
        other => Err(format!("unknown method: {other}")),
    }
}

// --- Domain sub-dispatchers ---

/// Node lifecycle, logs, and the peers table.
fn node_state(method: &str, params: Value) -> Result<Value, String> {
    match method {
        "getMobilePeerStatus" => json(api::get_mobile_peer_status()),
        "startNode" => json(api::start_node(parse(params)?)),
        "startNodeAuto" => json(api::start_node_auto()),
        "stopNode" => json(api::stop_node()),
        "getLogs" => ok(api::get_logs()),
        "clearLogs" => {
            api::clear_logs();
            ok(())
        }
        "getKnownPeers" => json(api::get_known_peers()),
        "getPeersWithStats" => json(mobile_api::get_peers_with_stats()),
        "sortPeers" => {
            let p: SortPeersParams = parse(params)?;
            ok(mobile_api::sort_peers(p.rows, p.sort_column, p.ascending))
        }
        other => Err(format!("method not routed to node_state: {other}")),
    }
}

/// Broadcast + DM message history and sends.
fn messages(method: &str, params: Value) -> Result<Value, String> {
    match method {
        "loadBroadcastMessages" => {
            let p: LimitParams = parse(params)?;
            json(api::load_broadcast_messages(p.limit))
        }
        "loadDmMessages" => {
            let p: PeerLimitParams = parse(params)?;
            json(api::load_dm_messages(p.peer_id, p.limit))
        }
        "saveOutgoingBroadcast" => {
            let p: SendParams = parse(params)?;
            json(match (p.attachment_path, p.attachment) {
                (_, Some(att)) => {
                    mobile_node::save_outgoing_broadcast_attached(p.content, Some(att))
                }
                (path, None) => api::save_outgoing_broadcast(p.content, path),
            })
        }
        "saveOutgoingDm" => {
            let p: SendDmParams = parse(params)?;
            json(match (p.attachment_path, p.attachment) {
                (_, Some(att)) => {
                    mobile_node::save_outgoing_dm_attached(p.peer_id, p.content, Some(att))
                }
                (path, None) => api::save_outgoing_dm(p.peer_id, p.content, path),
            })
        }
        "saveIncomingMessage" => {
            let p: SaveIncomingParams = parse(params)?;
            json(api::save_incoming_message(
                p.content,
                p.peer_id,
                p.is_direct,
                p.nickname,
                p.latency,
            ))
        }
        other => Err(format!("method not routed to messages: {other}")),
    }
}

/// Group lifecycle and group chat.
fn groups(method: &str, params: Value) -> Result<Value, String> {
    match method {
        "createGroup" => {
            let p: NameParams = parse(params)?;
            json(api::create_group(&p.name))
        }
        "listGroups" => json(api::list_groups()),
        "loadGroupMessages" => {
            let p: GroupLimitParams = parse(params)?;
            json(api::load_group_messages(p.group_id, p.limit))
        }
        "saveOutgoingGroup" => {
            let p: SendGroupParams = parse(params)?;
            json(match (p.attachment_path, p.attachment) {
                (_, Some(att)) => {
                    mobile_node::save_outgoing_group_attached(p.group_id, p.content, Some(att))
                }
                (path, None) => api::save_outgoing_group(p.group_id, p.content, path),
            })
        }
        "acceptGroupInvite" => {
            let p: GroupIdParams = parse(params)?;
            json(api::accept_group_invite(p.group_id))
        }
        "deleteGroup" => {
            let p: GroupIdParams = parse(params)?;
            json(api::delete_group(p.group_id))
        }
        other => Err(format!("method not routed to groups: {other}")),
    }
}

